import test from 'node:test';import assert from 'node:assert/strict';
import {gardenStages,gardenSources,gardenBeds,gardenArtKeys,gardenArt,normalizeGarden} from '../src/garden.js';import {defaultFarm,normalizeFarm,farmAction,farmView,farmArtKey,returnToFarm,farmPlants,wildSeedObjects} from '../src/farm.js';import {objects,materials} from '../src/data.js';import {pathfind} from '../src/navigation.js';import {zones} from '../src/zones.js';import {getJournalEntries} from '../src/journal.js';
const act=(f,command,bed=0,seed)=>farmAction(f,{type:'garden',command,bed,seed}).farm;
const bean=()=>farmAction(defaultFarm(),{type:'collect',id:'bean'}).farm;
test('owned seed planting, watering and returning require distinct actions and never consume the bank',()=>{let f=bean();f=act(f,'plant',0,'bean');assert.equal(f.garden.plots[0].stage,0);assert.equal(returnToFarm(f).garden.plots[0].stage,0);f=act(f,'water');assert.equal(f.garden.plots[0].stage,0);for(let i=0;i<10;i++)f=act(f,'water');assert.equal(f.garden.plots[0].stage,0);f=returnToFarm(f);assert.equal(f.garden.plots[0].stage,1);assert.equal(f.garden.plots[0].watered,false);for(let i=0;i<10;i++)f=returnToFarm(f);assert.equal(f.garden.plots[0].stage,1);for(let i=0;i<2;i++)f=returnToFarm(act(f,'water'));assert.equal(f.garden.plots[0].stage,3);assert.deepEqual(f.seeds,['bean']);assert.deepEqual(f.garden.grown,['bean']);assert.equal(gardenStages.length,4);});
test('three beds grow independently; unwatered plants wait without decay and reload preserves queued growth',()=>{let f=bean();for(let i=0;i<3;i++)f=act(f,'plant',i,'bean');f=act(f,'water',1);f=normalizeFarm(JSON.parse(JSON.stringify(f)));assert.equal(f.garden.plots[1].watered,true);f=returnToFarm(f);assert.deepEqual(f.garden.plots.map(p=>p.stage),[0,1,0]);assert.deepEqual(normalizeFarm(JSON.parse(JSON.stringify(f))),f);});
test('unknown seeds, invalid beds and premature replacement/harvest do not erase a growing plant',()=>{let f=bean();assert.equal(act(f,'plant',0,'missing').garden.plots[0].seed,null);assert.deepEqual(act(f,'plant',99,'bean'),f);f=act(f,'plant',0,'bean');const original=structuredClone(f);f=act(f,'plant',0,'bean');f=act(f,'harvest');assert.deepEqual(f,original);assert.equal(normalizeGarden({plots:[{seed:'missing',stage:3}]},['bean']).plots[0].seed,null);});
test('mature harvest and replant are repeatable, keep permanent records and preserve engineered equipment',()=>{let f={...bean(),constructionModules:['pipe-kit'],upgrades:{water:'quartz'}};for(let round=0;round<2;round++){f=act(f,'plant',0,'bean');for(let i=0;i<3;i++)f=returnToFarm(act(f,'water'));f=act(f,'harvest');assert.ok(f.garden.plots[0].harvested);}assert.deepEqual(f.garden.grown,['bean']);assert.deepEqual(f.garden.harvested,['bean']);assert.deepEqual(f.constructionModules,['pipe-kit']);assert.equal(f.upgrades.water,'quartz');const records=getJournalEntries('experiments',new Set(),new Set(),objects,materials,f);assert.equal(records.length,1);assert.equal(records[0].id,'garden-grown-bean');});
test('starter and exploration collection retain seed origins and never grant unknown species',()=>{let f=act(defaultFarm(),'starter');assert.deepEqual(f.seeds,['bean']);assert.deepEqual(f.garden.sources.bean,['starter']);for(const origin of ['forest','hills','moon-pod'])f=farmAction(f,{type:'collect',id:'bean',origin}).farm;assert.equal(f.seeds.length,1);assert.equal(f.garden.sources.bean.length,4);assert.equal(farmAction(f,{type:'collect',id:'not-a-plant'}).farm.seeds.length,1);for(const o of objects.filter(o=>o.seed)){assert.ok(farmPlants.some(p=>p.id===o.seed));assert.ok(gardenSources[o.seedOrigin]);}assert.match(wildSeedObjects.find(o=>o.zone==='chapterMoon').text,/sealed.*no known native plants/);assert.equal(objects.find(o=>o.id==='plant').seed,'sunflower');});
test('garden screens and every owned seed stay reachable within native choice limits with distinct staged art',()=>{let f=defaultFarm();for(const p of farmPlants)f=farmAction(f,{type:'collect',id:p.id}).farm;for(const route of ['garden',...Array.from({length:3},(_,i)=>'bed:'+i),...Array.from({length:8},(_,i)=>'sow:0:'+i),...f.seeds.map(id=>'choose-bed:'+id)]){const v=farmView(f,route);assert.ok(v.actions.length<=5,route);assert.ok(gardenArtKeys.includes(farmArtKey(f,route)));}for(const id of f.seeds){let stages=[];let plant=act(f,'plant',0,id);for(let i=0;i<4;i++){stages.push(gardenArt(farmArtKey(plant,'bed:0')));if(i<3)plant=returnToFarm(act(plant,'water'));}assert.equal(new Set(stages).size,4,id);}for(const bed of gardenBeds)assert.ok(pathfind(zones.farm.spawn,[bed.x-65,bed.y+55],'farm').length,bed.id);});
test('old saves keep all seed and science progress while getting three empty beds',()=>{const old=normalizeFarm({seeds:['bean','bean','oak'],growth:4,pollen:3,pump:true,experiments:['growth'],garden:{plots:[{seed:'unknown',stage:2}],sources:{bean:['bad','forest','forest']}}});assert.deepEqual(old.seeds,['bean','oak']);assert.equal(old.growth,4);assert.equal(old.pump,true);assert.equal(old.garden.plots.length,3);assert.ok(old.garden.plots.every(p=>p.seed===null));assert.deepEqual(old.garden.sources.bean,['forest']);assert.equal(old.experiments[0],'growth');});
